/**
 * App.js
 * Componente raíz de la aplicación React
 * Define las rutas principales con React Router
 */

import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Home from './pages/Home';
import Cuestionario from './pages/Cuestionario';
import Resultado from './pages/Resultado';
import './App.css';

function App() {
  return (
    <Router>
      <div className="app">
        {/* Navbar fija */}
        <nav className="navbar">
          <div className="navbar-inner">
            <a href="/" className="navbar-brand">
              <span className="navbar-icon">🛡️</span>
              <span className="navbar-name">CyberAudit</span>
            </a>
            <span className="navbar-tagline">Herramienta de Autoevaluación</span>
          </div>
        </nav>

        {/* Contenido principal */}
        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/cuestionario/:normativaId" element={<Cuestionario />} />
            <Route path="/resultado" element={<Resultado />} />
            {/* Ruta 404 */}
            <Route path="*" element={
              <div className="page error-page">
                <h2>404 — Página no encontrada</h2>
                <a href="/" className="btn-primary">Volver al inicio</a>
              </div>
            } />
          </Routes>
        </main>

        {/* Footer */}
        <footer className="footer">
          <p>CyberAudit · Herramienta de Autoevaluación de Ciberseguridad · ISO 27001 · ENS</p>
        </footer>
      </div>
    </Router>
  );
}

export default App;
